export function stillOut(loans: Loan[]): Record<GearKind, number> {
  const result: Record<GearKind, number> = {
    boatKey: 0,
    windlass: 0,
    lifejacket: 0,
    mooringPin: 0,
    mallet: 0,
    waterKey: 0,
  };
  for (const loan of loans) {
    if (!isOpen(loan)) continue;
    for (const line of loan.lines) {
      result[line.kind] += Math.max(0, line.issued - line.back);
    }
  }
  return result;
}
